<template>
    <div class="home-main ">

        <!-- 初始界面 -->
        <div class="empty-state">
            <div class="centered-content">
                <!-- 顶部问候语 -->
                <span class="greeting">{{ greetingText }}</span>
                <span class="sub-greeting">{{ $t('howCanIHelp') }}</span>

                <input-ai-chat
                    ref="refInput"
                    @onSend="onClickSend"
                    v-model:uploadFiles="uploadFiles"
                    :initialModel="aiChatStore.getAIChatParams()?.model"
                    :initialThinking="aiChatStore.getAIChatParams()?.isThinking"
                    :initialEnableSearch="aiChatStore.getAIChatParams()?.enable_search"
                />

                <!-- 操作按钮区域 -->
                <div class="tools-container">
                    <div class="tools-row">
                        <div @click="clickTool(tool)" v-for="(tool, index) in displayTools" :key="index" class="tool-button">
                            <div class="tool-icon">
                                <l-img :src="tool.icon" w="16px" h="16px" />
                            </div>
                            <span class="tool-name">{{ $t(tool.name) }}</span>
                        </div>
                    </div>
                </div>

                <!-- 底部版权信息 -->
                <div class="footer-text">
                    {{ $t('termsText',{appName}) }}
                    <span @click="clickGoToTerms" class="terms-text">{{ $t('terms') }}</span>
                    <span class="and-text">{{ $t('and') }}</span>
                    <span @click="clickGoToPrivacyPolicy" class="terms-text">{{ $t('privacyPolicy') }}</span>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import inputAiChat from '../components/input-ai-chat.vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';
import { useUserStore } from '@/store/modules/user';
import { useAIChatStore } from '@/store/modules/AIChat';
import { routerToPrivacyPolicy, routerToTerms, routerToAlienChat } from '@/router/navigation';
import {ROUTER_PATHS} from '@/router/constants';
import lImg from '@/components/l-img.vue';
import { useConversationData } from '@/composables/useConversationData';
import { openWindow } from '@/router/navigation';
const { t } = useI18n();
const userStore = useUserStore();
const aiChatStore = useAIChatStore();
const router = useRouter();
const refInput = ref(null);
const uploadFiles = ref([]);

// 使用会话数据组合式函数
const { initializeData } = useConversationData();

const onClickSend = (params) => {
    console.log(params);
    refInput.value.isLoading = false;

    // 存储AI提问参数
    aiChatStore.setAIChatParams(params);

    // 跳转到外星人聊天页面
    routerToAlienChat();
};

const clickTool = (tool) => {
  if(!tool.path) return;
    //   router.push(tool.path);
    openWindow(tool.path);
};


// 显示的工具列表，只显示前三个
const displayTools = [
    { name: 'aiChatCompanion', icon: '/static/images/ai_chat_companion.png',path:ROUTER_PATHS.CREATE_CHARACTER },
    { name: 'textTool', icon: '/static/images/text_tool.png',path: ROUTER_PATHS.TEXT_TOOL },
    { name: 'imageAnalysis', icon: '/static/images/image_analysis.png',path: ROUTER_PATHS.IMAGE_TOOL },
    { name: 'textToImage', icon: '/static/images/text-to-image-icon.png',path: ROUTER_PATHS.TEXT_TO_IMAGE},
    { name: 'textToVideo', icon: '/static/images/text-to-video-icon.png',path: ROUTER_PATHS.TEXT_TO_VIDEO},
    { name: 'imageToVideo', icon: '/static/images/image-to-video-icon.png',path: ROUTER_PATHS.IMAGE_TO_VIDEO},
].filter(tool => !tool.isDev || import.meta.env.DEV);
const appName = ref(import.meta.env.VITE_APP_TITLE);
// 根据时间和用户名获取问候语
const greetingText = computed(() => {
    const hour = new Date().getHours();

    const userName = userStore.currentUser?.nickname || 'User';
    if (hour >= 0 && hour < 6) {
        return t('goodNight', { name: userName });
    } else if (hour >= 6 && hour < 12) {
        return t('goodMorning', { name: userName });
    } else if (hour >= 12 && hour < 18) {
        return t('goodAfternoon', { name: userName });
    } else {
        return t('goodEvening', { name: userName });
    }
});

// 跳转到隐私政策页面
const clickGoToPrivacyPolicy = () => {
    routerToPrivacyPolicy();
};

// 跳转到用户协议页面
const clickGoToTerms = () => {
    routerToTerms();
};

// 组件挂载时初始化历史会话数据
onMounted(async () => {
    console.log('VITE_BUILD_VERSION', import.meta.env.VITE_BUILD_VERSION);
    // 初始化历史会话数据
    try {
        await initializeData();
    } catch (error) {
        console.error(error);
    }
});
</script>

